//! Deterministic test-vector generation.
//!
//! The vectors are signed with a fixed, PUBLIC test key. It exists only so the
//! files can be regenerated byte-for-byte. Never use it for anything real.

use crate::header::{
    crc32, Header, HeaderError, HDR_VERSION, HEADER_SIZE, IMAGE_TYPE_APP, IMAGE_TYPE_BL2,
    MAX_PAYLOAD, OFF_CRC, OFF_MAGIC, OFF_PAYLOAD_SIZE, OFF_RESERVED, OFF_SALT, OFF_SIG,
    OFF_TYPE, OFF_VERSION,
};
use crate::hexutil::to_hex;
use crate::image::{build_image, sha256, verify_image, ImageParams, VerifyError};
use ed25519_dalek::SigningKey;

const TEST_SEED: [u8; 32] = [0xC3; 32];
const ATTACKER_SEED: [u8; 32] = [0xA7; 32];

pub struct Vector {
    pub file: &'static str,
    pub bytes: Vec<u8>,
    /// "ok" or the name of the expected error (see `error_code`)
    pub expect: &'static str,
    /// position in the verifier check order of image_header.md; 0 = length/framing check before step 1. None for valid images
    pub step: Option<u8>,
    pub secver: Option<u32>,
    pub description: &'static str,
}

pub fn test_signing_key() -> SigningKey {
    SigningKey::from_bytes(&TEST_SEED)
}

pub fn test_public_key() -> [u8; 32] {
    test_signing_key().verifying_key().to_bytes()
}

pub fn error_code(e: &VerifyError) -> &'static str {
    match e {
        VerifyError::BadPublicKey => "BadPublicKey",
        VerifyError::Header(h) => match h {
            HeaderError::TooShort(_) => "TooShort",
            HeaderError::BadMagic(_) => "BadMagic",
            HeaderError::UnsupportedVersion(_) => "UnsupportedVersion",
            HeaderError::CrcMismatch { .. } => "CrcMismatch",
            HeaderError::ReservedNotZero => "ReservedNotZero",
            HeaderError::UnknownImageType(_) => "UnknownImageType",
            HeaderError::BadPayloadSize(_) => "BadPayloadSize",
        },
        VerifyError::SizeMismatch { .. } => "SizeMismatch",
        VerifyError::DigestMismatch => "DigestMismatch",
        VerifyError::BadSignature => "BadSignature",
    }
}

/// result of the host reference verifier as a manifest code
pub fn outcome(pubkey: &[u8; 32], image: &[u8]) -> &'static str {
    match verify_image(pubkey, image) {
        Ok(_) => "ok",
        Err(e) => error_code(&e),
    }
}

fn pattern(n: usize) -> Vec<u8> {
    (0..n).map(|i| (i.wrapping_mul(7).wrapping_add(3) & 0xFF) as u8).collect()
}

fn build(
    image_type: u16,
    secver: u32,
    load: u32,
    salt: u8,
    payload: &[u8],
    key: &SigningKey,
) -> Vec<u8> {
    let p = ImageParams {
        image_type,
        security_version: secver,
        load_address: load,
        entry_point: load,
        nonce_salt: [salt; 16],
    };
    build_image(&p, payload, key).expect("vector parameters are valid")
}

fn refresh_crc(img: &mut [u8]) {
    let c = crc32(&img[..OFF_CRC]);
    img[OFF_CRC..OFF_CRC + 4].copy_from_slice(&c.to_le_bytes());
}

fn mutated(base: &[u8], f: impl FnOnce(&mut Vec<u8>)) -> Vec<u8> {
    let mut b = base.to_vec();
    f(&mut b);
    b
}

/// edit parsed header fields and re-encode; the CRC is fresh but the signature is the old one, so only the signature check can catch it
fn forge(base: &[u8], edit: impl FnOnce(&mut Header)) -> Vec<u8> {
    let mut h = Header::decode(base).expect("base image is valid");
    edit(&mut h);
    let mut out = h.encode().to_vec();
    out.extend_from_slice(&base[HEADER_SIZE..]);
    out
}

fn mk(
    file: &'static str,
    bytes: Vec<u8>,
    expect: &'static str,
    step: Option<u8>,
    secver: Option<u32>,
    description: &'static str,
) -> Vector {
    Vector { file, bytes, expect, step, secver, description }
}

pub fn generate() -> Vec<Vector> {
    let key = test_signing_key();
    let attacker = SigningKey::from_bytes(&ATTACKER_SEED);

    let app1 = build(IMAGE_TYPE_APP, 1, 0x4002_0100, 0x01, &pattern(64), &key);
    let app2 = build(IMAGE_TYPE_APP, 2, 0x4002_0100, 0x02, &pattern(64), &key);
    let bl2 = build(IMAGE_TYPE_BL2, 1, 0x4000_0100, 0x03, &pattern(128), &key);
    let tiny = build(IMAGE_TYPE_APP, 1, 0x4002_0100, 0x04, &pattern(1), &key);

    vec![
        // ---- valid -------------------------------------------------------
        mk("valid_app_secver1.img", app1.clone(), "ok", None, Some(1),
           "Valid app image, security version 1, 64-byte payload"),
        mk("valid_app_secver2.img", app2, "ok", None, Some(2),
           "Valid app image, security version 2 (for rollback tests)"),
        mk("valid_bl2_secver1.img", bl2, "ok", None, Some(1),
           "Valid BL2 image, 128-byte payload"),
        mk("valid_app_min_payload.img", tiny, "ok", None, Some(1),
           "Valid app image with the minimum payload of 1 byte"),
        // ---- framing -----------------------------------------------------
        mk("bad_header_too_short.img", app1[..HEADER_SIZE - 1].to_vec(), "TooShort", Some(0), None,
           "Image shorter than the 256-byte header"),
        mk("bad_truncated.img", app1[..app1.len() - 1].to_vec(), "SizeMismatch", Some(0), None,
           "Last payload byte missing"),
        // ---- structural checks (steps 1-6) ----------------------------------
        mk("bad_magic.img", mutated(&app1, |b| b[OFF_MAGIC] ^= 0xFF), "BadMagic", Some(1), None,
           "First magic byte flipped"),
        mk("bad_version.img",
           mutated(&app1, |b| { b[OFF_VERSION] = 2; refresh_crc(b); }),
           "UnsupportedVersion", Some(2), None,
           "HDR_VERSION set to 2, CRC recomputed"),
        mk("bad_crc.img", mutated(&app1, |b| b[OFF_SALT] ^= 0x01), "CrcMismatch", Some(3), None,
           "One salt bit flipped, CRC left stale"),
        mk("bad_reserved_nonzero.img",
           mutated(&app1, |b| { b[OFF_RESERVED + 8] = 1; refresh_crc(b); }),
           "ReservedNotZero", Some(4), None,
           "Non-zero byte in the reserved area, CRC recomputed"),
        mk("bad_image_type.img",
           mutated(&app1, |b| { b[OFF_TYPE] = 9; refresh_crc(b); }),
           "UnknownImageType", Some(5), None,
           "IMAGE_TYPE set to 0x0009, CRC recomputed"),
        mk("bad_payload_size_zero.img",
           mutated(&app1, |b| {
               b[OFF_PAYLOAD_SIZE..OFF_PAYLOAD_SIZE + 4].copy_from_slice(&0u32.to_le_bytes());
               refresh_crc(b);
           }),
           "BadPayloadSize", Some(6), None,
           "PAYLOAD_SIZE = 0, CRC recomputed"),
        mk("bad_payload_size_too_large.img",
           mutated(&app1, |b| {
               b[OFF_PAYLOAD_SIZE..OFF_PAYLOAD_SIZE + 4]
                   .copy_from_slice(&(MAX_PAYLOAD + 1).to_le_bytes());
               refresh_crc(b);
           }),
           "BadPayloadSize", Some(6), None,
           "PAYLOAD_SIZE = max_payload + 1, CRC recomputed"),
        // cryptographic checks (steps 9-10)
        mk("bad_digest.img", mutated(&app1, |b| b[HEADER_SIZE] ^= 0x01), "DigestMismatch", Some(9), None,
           "First payload byte flipped, header untouched"),
        mk("bad_signature_bitflip.img",
           mutated(&app1, |b| { b[OFF_SIG] ^= 0x01; refresh_crc(b); }),
           "BadSignature", Some(10), None,
           "One signature bit flipped, CRC recomputed"),
        mk("bad_signature_wrong_key.img",
           build(IMAGE_TYPE_APP, 1, 0x4002_0100, 0x05, &pattern(64), &attacker),
           "BadSignature", Some(10), None,
           "Well-formed image signed by a different key"),
        mk("forged_secver.img",
           forge(&app1, |h| h.security_version = 0),
           "BadSignature", Some(10), Some(0),
           "Security version lowered to 0 with a fresh CRC (rollback attempt)"),
        mk("forged_load_address.img",
           forge(&app1, |h| h.load_address = 0x2000_0000),
           "BadSignature", Some(10), None,
           "Load address redirected to SRAM with a fresh CRC"),
    ]
}

/// manifest.toml describing every vector, for the other components to consume
pub fn manifest(vectors: &[Vector]) -> String {
    let pk = test_public_key();
    let mut s = String::new();
    s.push_str("# Generated by `cerberus-cli vectors`. Do not edit by hand.\n");
    s.push_str("# Signed with a PUBLIC test key. Never use it for anything real.\n");
    s.push_str("# step = position in the verifier check order of image_header.md;\n");
    s.push_str("#        0 = length/framing check before step 1.\n\n");
    s.push_str("[meta]\n");
    s.push_str(&format!("header_version = {}\n", HDR_VERSION));
    s.push_str(&format!("pubkey = \"{}\"\n", to_hex(&pk)));
    s.push_str(&format!("pubkey_sha256 = \"{}\"\n", to_hex(&sha256(&pk))));
    for v in vectors {
        s.push_str("\n[[vector]]\n");
        s.push_str(&format!("file = \"{}\"\n", v.file));
        s.push_str(&format!("expect = \"{}\"\n", v.expect));
        if let Some(step) = v.step {
            s.push_str(&format!("step = {step}\n"));
        }
        if let Some(sv) = v.secver {
            s.push_str(&format!("secver = {sv}\n"));
        }
        s.push_str(&format!("description = \"{}\"\n", v.description));
    }
    s
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn all_vectors_produce_expected_outcome() {
        let pk = test_public_key();
        for v in generate() {
            assert_eq!(outcome(&pk, &v.bytes), v.expect, "vector {}", v.file);
        }
    }

    #[test]
    fn generation_is_deterministic() {
        let a: Vec<Vec<u8>> = generate().into_iter().map(|v| v.bytes).collect();
        let b: Vec<Vec<u8>> = generate().into_iter().map(|v| v.bytes).collect();
        assert_eq!(a, b);
    }

    #[test]
    fn file_names_are_unique() {
        let vs = generate();
        let mut names: Vec<&str> = vs.iter().map(|v| v.file).collect();
        names.sort_unstable();
        let n = names.len();
        names.dedup();
        assert_eq!(names.len(), n);
    }

    #[test]
    fn every_error_kind_is_covered() {
        let vs = generate();
        for code in [
            "TooShort", "BadMagic", "UnsupportedVersion", "CrcMismatch", "ReservedNotZero",
            "UnknownImageType", "BadPayloadSize", "SizeMismatch", "DigestMismatch", "BadSignature",
        ] {
            assert!(vs.iter().any(|v| v.expect == code), "no vector for {code}");
        }
    }

    #[test]
    fn manifest_lists_every_vector() {
        let vs = generate();
        let m = manifest(&vs);
        for v in &vs {
            assert!(m.contains(&format!("file = \"{}\"", v.file)), "{}", v.file);
        }
    }
}
